import Foundation

/// The driver's settings: what each one is called, where it lives (a boot argument or a line in nvrm610.conf), which values
/// it accepts, and how to change it without disturbing anything else. The catalogue is data (Resources/settings_catalog.json,
/// generated by the driver's tools/nullmoth_settings.py) and this file is a port of that tool's rules; the test in
/// tests/settings runs both against the same vectors, so a setting is valid in the window exactly when it is on the command line.
enum DriverSettings {
    struct Setting {
        let id, group, title, where_, key, kind, help, effect: String
        let values: [String: String]?
        let range: (Int, Int)?
    }
    struct Catalog {
        let confPath, blockStart, blockEnd: String
        let kept: NSRegularExpression
        let settings: [Setting]
        func find(_ id: String) -> Setting? { settings.first { $0.id == id } }
    }
    enum Bad: Error, Equatable { case refused(String) }

    static func load(_ data: Data) -> Catalog? {
        guard let j = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let path = j["conf_path"] as? String, let a = j["block_start"] as? String, let b = j["block_end"] as? String,
              let pat = j["kept_pattern"] as? String, let re = try? NSRegularExpression(pattern: pat),
              let list = j["settings"] as? [[String: Any]] else { return nil }
        let settings: [Setting] = list.compactMap { d in
            guard let id = d["id"] as? String, let g = d["group"] as? String, let t = d["title"] as? String, let w = d["where"] as? String,
                  let k = d["key"] as? String, let kind = d["kind"] as? String, let h = d["help"] as? String, let e = d["effect"] as? String else { return nil }
            var r: (Int, Int)? = nil
            if let a = d["rng"] as? [Int], a.count == 2 { r = (a[0], a[1]) }
            return Setting(id: id, group: g, title: t, where_: w, key: k, kind: kind, help: h, effect: e, values: d["values"] as? [String: String], range: r)
        }
        guard settings.count == list.count else { return nil }
        return Catalog(confPath: path, blockStart: a, blockEnd: b, kept: re, settings: settings)
    }

    private static func digits(_ s: String) -> Bool { !s.isEmpty && s.utf8.allSatisfy { $0 >= 48 && $0 <= 57 } }

    /// The text to store, or nil for "default" (remove the setting). Throws with the reason for a value outside the setting's rules.
    static func normalize(_ c: Catalog, _ s: Setting, _ value: String) throws -> String? {
        let v = value.trimmingCharacters(in: .whitespacesAndNewlines)
        let low = v.lowercased()
        if ["default", "auto", "automatic", "unset"].contains(low) { return nil }
        switch s.kind {
        case "bool":
            if ["on", "yes", "true", "1"].contains(low) { return "1" }
            if ["off", "no", "false", "0"].contains(low) { return "0" }
            throw Bad.refused("\(s.id) takes on, off or default")
        case "enum":
            if let m = s.values?[low] { return m }
            if let vals = s.values, vals.values.contains(v) { return v }
            throw Bad.refused("\(s.id) takes one of \((s.values ?? [:]).keys.sorted().joined(separator: ", ")) or default")
        case "int":
            let zeroOK = ["surround", "vibrance", "shader-cache-mb"].contains(s.id)
            guard digits(v), let n = Int(v), let r = s.range else { throw Bad.refused("\(s.id) takes a number") }
            if !(r.0 <= n && n <= r.1) && !(zeroOK && n == 0) { throw Bad.refused("\(s.id) takes a number from \(r.0) to \(r.1), or default") }
            return String(n)
        default:
            if s.id == "card" {
                for e in (v.contains("=") ? v.components(separatedBy: ",") : [v]) {
                    let parts = e.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)
                    let num = parts.count == 2 ? String(parts[1]) : e
                    if parts.count == 2 && parts[0].isEmpty { throw Bad.refused("card: an entry needs an application name or *") }
                    guard num.count == 1, let c = num.first, c >= "0" && c <= "7" else { throw Bad.refused("card: \(num) is not a card number from 0 to 7") }
                }
            }
            if s.id == "fps-limit" {
                let entries = v.contains("=") ? v.components(separatedBy: ",") : [v]
                for e in entries {
                    let parts = e.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)
                    let num = parts.count == 2 ? String(parts[1]) : e
                    if parts.count == 2 && parts[0].isEmpty { throw Bad.refused("fps-limit: an entry needs an application name or *") }
                    guard digits(num), let n = Int(num), n == 0 || (10...1000).contains(n) else {
                        throw Bad.refused("fps-limit: \(num) is not 0 or a number from 10 to 1000")
                    }
                }
            }
            let line = s.key + "=" + v
            if c.kept.firstMatch(in: line, range: NSRange(line.startIndex..., in: line)) == nil {
                throw Bad.refused("\(s.id): characters an update would not keep")
            }
            return v
        }
    }

    // MARK: boot arguments
    static func bootargsSet(_ line: String, _ key: String, _ value: String?) -> String {
        var out: [String] = [], seen = false
        for tok in line.split(whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\n" }).map(String.init) {
            if tok.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)[0] == key {
                if let v = value, !seen { out.append("\(key)=\(v)") }
                seen = true
            } else { out.append(tok) }
        }
        if let v = value, !seen { out.append("\(key)=\(v)") }
        return out.joined(separator: " ")
    }
    static func bootargsGet(_ line: String, _ key: String) -> String? {
        for tok in line.split(whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\n" }).map(String.init) {
            let p = tok.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false).map(String.init)
            if p[0] == key { return p.count == 2 ? p[1] : "" }
        }
        return nil
    }
    /// A boot line the panel may rewrite: plain tokens only, so that putting it back through nvram cannot change meaning.
    static func bootargsSafe(_ line: String) -> Bool {
        line.unicodeScalars.allSatisfy { ($0.value >= 48 && $0.value <= 57) || ($0.value >= 65 && $0.value <= 90) || ($0.value >= 97 && $0.value <= 122) || "_=.,:/@- ".unicodeScalars.contains($0) }
    }

    // MARK: nvrm610.conf user block
    private static func splitLines(_ t: String) -> [String] {
        var l = t.components(separatedBy: "\n"); if l.last == "" { l.removeLast() }; return l
    }
    static func confSet(_ c: Catalog, _ text: String, _ key: String, _ value: String?) -> String {
        var lines = splitLines(text)
        func keyOf(_ l: String) -> String { String(l.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false)[0]) }
        if let a = lines.firstIndex(of: c.blockStart), let b = lines[a...].firstIndex(of: c.blockEnd) {
            var body = Array(lines[(a + 1)..<b]).filter { keyOf($0) != key }
            if let v = value { body.append("\(key)=\(v)") }
            lines.replaceSubrange(a...b, with: body.isEmpty ? [] : [c.blockStart] + body + [c.blockEnd])
        } else if let v = value {
            lines += [c.blockStart, "\(key)=\(v)", c.blockEnd]
        }
        return lines.joined(separator: "\n") + "\n"
    }
    static func confGet(_ c: Catalog, _ text: String, _ key: String) -> String? {
        var inside = false, val: String? = nil
        for l in text.components(separatedBy: "\n") {
            if l == c.blockStart { inside = true } else if l == c.blockEnd { inside = false }
            else if inside {
                let p = l.split(separator: "=", maxSplits: 1, omittingEmptySubsequences: false).map(String.init)
                if p[0] == key { val = p.count == 2 ? p[1] : "" }
            }
        }
        return val
    }

    // MARK: the change itself
    enum Change: Equatable {
        case bootArgs(String)     // the whole new boot-args line
        case conf(String)         // the whole new nvrm610.conf
    }
    /// What setting `s` to `value` would do given today's boot line and conf. Nothing is written here.
    static func plan(_ c: Catalog, _ s: Setting, _ value: String, bootArgs: String, conf: String) throws -> Change {
        let v = try normalize(c, s, value)
        if s.where_ == "bootarg" {
            guard bootargsSafe(bootArgs) else { throw Bad.refused("the current boot arguments hold characters this panel will not rewrite; change them by hand") }
            return .bootArgs(bootargsSet(bootArgs, s.key, v))
        }
        let new = confSet(c, conf, s.key, v)
        if let bad = userBlockLines(c, new).first(where: { c.kept.firstMatch(in: $0, range: NSRange($0.startIndex..., in: $0)) == nil }) {
            throw Bad.refused("the line \(bad) in your settings block would not survive an update")
        }
        return .conf(new)
    }
    static func userBlockLines(_ c: Catalog, _ text: String) -> [String] {
        let l = splitLines(text)
        guard let a = l.firstIndex(of: c.blockStart), let b = l[a...].firstIndex(of: c.blockEnd) else { return [] }
        return Array(l[(a + 1)..<b])
    }

    static func shellQuote(_ s: String) -> String { "'" + s.replacingOccurrences(of: "'", with: "'\\''") + "'" }

    /// The root command that makes the change. The conf is written by root into a file root creates beside it and renamed over
    /// it, so another user's process cannot swap anything between the check and the write.
    static func command(_ c: Catalog, _ change: Change, owner: String = "root:wheel") -> String {
        switch change {
        case .bootArgs(let line):
            return "/usr/sbin/nvram boot-args=\(shellQuote(line))"
        case .conf(let text):
            let q = shellQuote
            return "d=$(/usr/bin/dirname \(q(c.confPath))); t=$(/usr/bin/mktemp \"$d/.nvrm610.XXXXXX\") || exit 1; "
                + "/usr/bin/printf '%s' \(q(text)) > \"$t\" && /bin/chmod 644 \"$t\" && /usr/sbin/chown \(owner) \"$t\" && /bin/mv \"$t\" \(q(c.confPath)) || { /bin/rm -f \"$t\"; exit 1; }"
        }
    }
}
